// Scroll-driven stories (pages/stories/<id>.html, generated by pipeline/render_stories.py).
// The step texts are in the page; this script adds the sticky chart and redraws it as each step
// reaches the middle of the screen. Two chart types: "lines" (a time series that unfolds year by
// year, with notes) and "dots" (one dot per apprenticeship scheme, regrouped and highlighted).

const NS = 'http://www.w3.org/2000/svg';
const W = 640, H = 420;
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;

const story = document.getElementById('story');
const data = JSON.parse(document.getElementById('st-data').textContent);
const chartEl = document.getElementById('st-chart');
const capEl = document.getElementById('st-cap');
const steps = [...document.querySelectorAll('.st-step')];

function el(tag, attrs = {}, parent) {
  const n = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
  if (parent) parent.appendChild(n);
  return n;
}
const fmt = v => Math.round(v).toLocaleString('en-GB');
const short = v => v >= 1e6 ? (v / 1e6).toFixed(v % 1e6 ? 1 : 0) + 'M' : v >= 1e3 ? Math.round(v / 1e3) + 'k' : String(v);

// One animation at a time: a newer step cancels the one still running.
let tweenId = 0;
function tween(from, to, ms, fn) {
  const id = ++tweenId;
  if (reduced || from === to) { fn(to); return; }
  const t0 = performance.now();
  const tick = now => {
    if (id !== tweenId) return;
    const k = Math.min(1, (now - t0) / ms);
    const e = 1 - Math.pow(1 - k, 3);
    fn(from + (to - from) * e);
    if (k < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
  // Browsers pause animation frames in background tabs: make sure the step still ends in its final state.
  setTimeout(() => { if (id === tweenId) fn(to); }, ms + 80);
}

// ---------------------------------------------------------------- lines --

function linesChart(spec) {
  const M = { l: 58, r: 150, t: 34, b: 36 };
  const svg = el('svg', { viewBox: `0 0 ${W} ${H}`, class: 'st-svg' });
  chartEl.appendChild(svg);
  let clipW = 0, view = null;
  const clipId = 'st-clip';
  const defs = el('defs', {}, svg);
  const clip = el('rect', { x: 0, y: 0, width: 0, height: H }, el('clipPath', { id: clipId }, defs));
  const grid = el('g', { class: 'st-grid' }, svg);
  const notes = el('g', { class: 'st-notes' }, svg);
  const plot = el('g', { 'clip-path': `url(#${clipId})` }, svg);
  const marks = el('g', {}, svg);

  function draw(state) {
    const isIndex = state.view === 'index';
    const all = isIndex
      ? spec.index.series.map((s, i) => ({ key: 'i' + i, label: s.label.split(' — ')[0], points: s.points }))
      : (state.series || ['TOTAL']).map(k => ({ key: k, label: spec.labels[k], points: spec.series[k].points }));
    const years = [...new Set((isIndex ? all : Object.values(spec.series)).flatMap(s => s.points.map(p => p.time)))].sort();
    const x0 = +years[0], x1 = +years[years.length - 1];
    const X = t => M.l + (W - M.l - M.r) * ((+t - x0) / (x1 - x0 || 1));
    const scopeKey = isIndex ? 'index' : (state.series || ['TOTAL']).join();
    const maxV = Math.max(...all.flatMap(s => s.points.map(p => p.value)));
    const step = niceStep(isIndex ? (maxV - 50) / 4 : maxV / 5);
    const minV = isIndex ? Math.floor(Math.min(...all.flatMap(s => s.points.map(p => p.value))) / step) * step : 0;
    const top = Math.ceil(maxV / step) * step;
    const Y = v => H - M.b - (H - M.t - M.b) * ((v - minV) / (top - minV));

    if (view !== scopeKey) {
      view = scopeKey;
      grid.replaceChildren(); plot.replaceChildren();
      for (let v = minV; v <= top + 1e-9; v += step) {
        el('line', { x1: M.l, x2: W - M.r + 10, y1: Y(v), y2: Y(v) }, grid);
        el('text', { x: M.l - 8, y: Y(v) + 4, 'text-anchor': 'end' }, grid).textContent = isIndex ? Math.round(v) : short(v);
      }
      for (const t of years) if ((+t - x0) % 2 === 0 || +t === x1)
        el('text', { x: X(t), y: H - M.b + 20, 'text-anchor': 'middle' }, grid).textContent = t;
      if (isIndex) el('line', { class: 'st-base', x1: M.l, x2: W - M.r + 10, y1: Y(100), y2: Y(100) }, grid);
      all.forEach((s, i) => {
        const d = s.points.map((p, j) => `${j ? 'L' : 'M'}${X(p.time).toFixed(1)},${Y(p.value).toFixed(1)}`).join('');
        el('path', { d, class: `st-line st-c${i}` }, plot);
        const lp = s.points[s.points.length - 1];
        const lab = el('text', { x: X(lp.time) + 8, y: Y(lp.value) + 4, class: `st-lab st-c${i}` }, plot);
        lab.textContent = s.label;
      });
      clipW = isIndex ? 0 : clipW;
    }
    // Reveal up to the step's year (all of it for the index view).
    const target = isIndex ? W : X(state.upto) + 2;
    const labelsRoom = isIndex || state.upto === String(x1) ? W : target;
    tween(clipW, labelsRoom, 900, w => { clip.setAttribute('width', w); clipW = w; });

    notes.replaceChildren();
    for (const n of state.notes || []) {
      const g = el('g', { class: 'st-note' }, notes);
      el('line', { x1: X(n.time), x2: X(n.time), y1: M.t - 6, y2: H - M.b }, g);
      el('text', { x: X(n.time) + 4, y: M.t - 10 }, g).textContent = n.label;
    }
    marks.replaceChildren();
    if (state.mark) {
      all.forEach((s, i) => {
        const p = s.points.find(q => q.time === state.mark);
        if (!p) return;
        el('circle', { cx: X(p.time), cy: Y(p.value), r: 5.5, class: `st-dot st-c${i}` }, marks);
        const t = el('text', { x: X(p.time) - 8, y: Y(p.value) - 12, 'text-anchor': 'end', class: 'st-val' }, marks);
        t.textContent = fmt(p.value);
      });
    }
    capEl.textContent = isIndex ? `National series, ${spec.index.unit}` : `France: ${spec.unit}`;
  }
  return draw;
}

function niceStep(raw) {
  const p = Math.pow(10, Math.floor(Math.log10(raw)));
  for (const m of [1, 2, 2.5, 5, 10]) if (m * p >= raw) return m * p;
  return 10 * p;
}

// ---------------------------------------------------------------- dots --

function dotsChart(spec) {
  const svg = el('svg', { viewBox: `0 0 ${W} ${H}`, class: 'st-svg st-dots' });
  chartEl.appendChild(svg);
  const heads = el('g', { class: 'st-heads' }, svg);
  const nodes = spec.dots.map(d => {
    const g = el('g', { class: `st-d st-f-${d.family}` }, svg);
    el('title', {}, g).textContent = `${d.name} (${d.country})`;
    el('circle', { r: 19 }, g);
    el('text', { y: 4, 'text-anchor': 'middle' }, g).textContent = d.cc;
    return { d, g };
  });
  const pos = new Map();

  function gridLayout() {
    const cols = 9, gap = 50, rows = Math.ceil(nodes.length / cols);
    const x0 = (W - (cols - 1) * gap) / 2, y0 = (H - (rows - 1) * gap) / 2;
    nodes.forEach((n, i) => pos.set(n, [x0 + (i % cols) * gap, y0 + Math.floor(i / cols) * gap]));
    heads.replaceChildren();
  }
  function familyLayout(outcome) {
    heads.replaceChildren();
    const groups = [['employer', 70, 5], ['school', 360, 5], ['other', 360, 2]];
    const gap = 46;
    let otherY = 0;
    for (const [fam, gx, cols] of groups) {
      const members = nodes.filter(n => n.d.family === fam);
      if (!members.length) continue;
      const gy = fam === 'other' ? otherY : 86;
      members.forEach((n, i) => pos.set(n, [gx + 23 + (i % cols) * gap, gy + Math.floor(i / cols) * gap]));
      const rows = Math.ceil(members.length / cols);
      if (fam === 'school') otherY = gy + rows * gap + 52;
      const label = `${spec.families[fam]} · ${members.length}`;
      const t = el('text', { x: gx, y: gy - 36, class: 'st-ghead' }, heads);
      t.textContent = label;
    }
  }
  function apply() {
    for (const n of nodes) {
      const [x, y] = pos.get(n);
      n.g.style.transform = `translate(${x}px, ${y}px)`;
    }
  }
  return state => {
    if (state.layout === 'families') familyLayout(state.outcome); else gridLayout();
    apply();
    for (const n of nodes) n.g.classList.toggle('st-on', !!(state.on && n.d[state.on]));
    svg.classList.toggle('st-dim', !!state.on);
    capEl.textContent = state.on ? `Highlighted: ${spec.flags[state.on]}` : (state.layout === 'families' ? 'Schemes by family' : 'One dot per apprenticeship scheme');
  };
}

// ---------------------------------------------------------------- scroll --

const draw = data.chart.type === 'dots' ? dotsChart(data.chart) : linesChart(data.chart);
story.classList.add('st-js');
let current = -1;
function activate(i) {
  if (i === current) return;
  current = i;
  steps.forEach((s, j) => s.classList.toggle('is-active', j === i));
  draw(data.steps[i]);
}
activate(0);
const io = new IntersectionObserver(entries => {
  for (const en of entries) if (en.isIntersecting) activate(+en.target.dataset.step);
}, { rootMargin: '-48% 0px -48% 0px' });
steps.forEach(s => io.observe(s));
